import json,hashlib
P='/tmp/mindbattle-weather-source-01a1375b-4604-7b63-aee5-36b19c570e5d/final.json'
d=json.load(open(P)); cards={c['index']:c for c in d['cards']}
# prompt, answers(text,note), explanation, reason sets (two distinct source/editorial reasons per group)
D={
20:("A parcel starts 5°C warmer than its surroundings. It rises 1 km through air cooling at 5°C/km, then enters a layer cooling at 8°C/km. The unsaturated parcel cools at 9.8°C/km. At what height above the start does it first become neutrally buoyant?",[("About 1.11 km","After the first kilometre, the parcel is 0.2°C warmer: its 9.8°C drop exceeds the environment's 5°C drop by 4.8°C, subtracted from the initial 5°C excess."),("At 1.00 km","At the layer boundary it still has a 0.2°C positive temperature excess; neutrality occurs only after entering the faster-cooling second layer."),("About 1.27 km","This would require the second-layer relative cooling rate to be about 1.5°C/km; the stated 9.8 and 8°C/km rates differ by 1.8°C/km."),("It remains positively buoyant","In the second layer the parcel cools 1.8°C/km faster than its environment, so the remaining 0.2°C excess is removed." )],"At 1 km the parcel/environment temperature difference is 5 − (9.8−5)=0.2°C. In the next layer that margin shrinks at 9.8−8=1.8°C/km, so it reaches zero after 0.2/1.8≈0.11 km, or 1.11 km total.", ["NWS defines the dry adiabatic rate for an unsaturated parcel; the two environmental rates are explicit sounding inputs in the stem.","The answer requires carrying the parcel-environment temperature difference across a layer boundary, then solving for the zero crossing using the new rate."], ["The 9.8°C/km dry rate gives a 4.8°C relative loss in layer one, leaving the stated 0.2°C margin.","The key's extra 0.11 km follows from dividing that residual margin by the 1.8°C/km relative cooling in layer two."]),
21:("An unsaturated parcel begins 2°C warmer than its environment. It reaches its lifting condensation level at 1 km; below that, the environmental lapse rate is 6°C/km. Above it, the saturated parcel cools at 5°C/km while the environment cools at 7°C/km. Where does the parcel next become neutrally buoyant?",[("At 1.9 km","The parcel loses 3.8°C of its initial 2°C advantage below the LCL, leaving it 1.8°C colder; above the LCL its advantage grows by 2°C/km and returns to zero after 0.9 km."),("At the LCL","At 1 km it is already 1.8°C colder than the environment, so reaching saturation does not itself restore neutrality."),("It never becomes neutral","Above the LCL the environment cools faster than the saturated parcel, reversing the temperature-difference trend and restoring positive buoyancy."),("At 2.8 km","This adds the below-LCL and above-LCL distances as though the parcel retained its original positive margin at saturation." )],"Below the LCL the parcel's relative change is −(9.8−6)=−3.8°C, leaving a −1.8°C margin at 1 km. Above it, the margin increases at 7−5=2°C/km; 0.9 km later it reaches zero, at 1.9 km.",["NWS distinguishes dry and moist adiabatic changes by parcel saturation; the LCL marks the transition in the specified parcel history.","This item makes the solver propagate a signed buoyancy margin through both regimes instead of selecting one lapse rate for the whole ascent."],["The key uses the dry-rate deficit to calculate the −1.8°C margin at the LCL, then the 2°C/km moist-layer advantage to locate its return to zero.","The 1.9-km result is a second neutral crossing; the parcel is negatively buoyant between 1 and 1.9 km despite beginning warmer."]),
22:("A sounding cools 18→11°C from 0–1 km and 11→3°C from 1–2 km. Compare an unsaturated parcel (9.8°C/km) and a saturated parcel (5°C/km in the first layer, 6°C/km in the second) with the environment. Which conclusion follows?",[("Both parcels lose buoyancy in both layers","This treats every parcel as if it cooled faster than the environment; the environment's 7 and 8°C/km rates exceed the saturated rates."),("The unsaturated parcel loses buoyancy, while the saturated parcel gains it in both layers","The environmental rates 7 and 8 lie below the dry rate 9.8 but above the moist rates 5 and 6; the relative temperature changes therefore have opposite signs."),("Both parcels gain buoyancy in both layers","This would require the environment to cool faster than each parcel; it does not cool faster than the dry parcel."),("The environment is isothermal","The readings show drops of 7°C and 8°C per kilometre, not constant temperature." )],"The environment cools at 7°C/km then 8°C/km. A dry parcel cooling at 9.8°C/km becomes colder relative to the environment in both layers; a saturated parcel cooling at 5 then 6°C/km stays warmer relative to it. This is conditional stability: the comparison depends on saturation.",["NWS defines environmental lapse rate from observed temperature change with height and treats it separately from parcel adiabatic rates.","The two measured layers straddle the moist rates but remain below the dry rate, so one profile produces different stability signs by parcel state."],["The correct conclusion compares 9.8 against both observed rates and separately compares 5/6 against those same rates.","The explanation identifies why dry and saturated parcels have opposite buoyancy tendencies without treating a single layer average as sufficient."]),
23:("A sounding shows a warm, moist low-level layer beneath a stable warm-over-cool layer. Lifted parcels remain colder than their surroundings within that layer, while CAPE exists above it. A front is forecast to lift and cool the cap. Which outcome is most consistent?",[("CAPE above the cap guarantees immediate surface thunderstorms","Positive energy aloft does not remove the stable layer that currently prevents surface parcels from reaching free convection."),("The cap permanently eliminates instability","A cap inhibits ascent while intact; it can weaken or be lifted, so it does not erase the energy stored above it."),("Convection may be delayed, then intensify rapidly if the cap erodes","The stable layer suppresses parcels for now, while warm moist air and CAPE can support vigorous release after sufficient lifting or cooling weakens the cap."),("The front strengthens the cap because it lifts air","The stated forecast includes cooling and lifting, which can reduce inhibition; lifting alone does not imply reinforcement." )],"The warm-over-cool stable layer is a cap: parcels lifted into it are colder than their environment and are inhibited. If frontal lifting/cooling erodes that barrier, the moist low-level air can reach the positive-buoyancy layer and release stored instability quickly.",["NWS describes an inversion as temperature increasing with height, a profile that resists vertical mixing and can act as a lid.","The stem supplies both inhibition within the cap and available energy above it; the forecast change targets the barrier rather than removing CAPE."],["The correct forecast preserves the present inhibition while allowing a later transition if the cap erodes.","The warm moist source layer and positive buoyancy above the cap explain why release can be rapid once parcels are no longer trapped."]),
24:("A sounding parcel has CAPE = 1,250 J/kg, positive buoyancy from its LFC to EL, and remains colder than the environment above EL. Ignore entrainment and water loading. Using SPC's idealized estimate √(2 × CAPE), what is its maximum updraft speed estimate?",[("25 m/s","25²/2 = 312.5 J/kg, so this speed corresponds to far less CAPE than the sounding value."),("35 m/s","This estimate is below √2500; it would correspond to CAPE of 612.5 J/kg."),("40 m/s","40²/2 = 800 J/kg, which underestimates the specified parcel energy."),("50 m/s","√(2 × 1250)=√2500=50 m/s; the estimate comes from converting the parcel's buoyant energy to vertical speed." )],"SPC's idealized maximum-speed estimate is √(2×CAPE). Substitution gives √2500=50 m/s. The parcel's negative buoyancy above EL is separate: momentum may carry it beyond EL toward the maximum parcel level, so EL is not automatically the updraft's stopping point.",["SPC's parcel-values guidance gives the idealized maximum updraft relation and distinguishes CAPE from the levels where buoyancy changes sign.","The stem combines an energy calculation with a vertical-profile distinction: positive buoyancy ends at EL, while momentum can carry the parcel above it."],["The keyed value is the direct square root of twice the stated 1,250 J/kg, under the expressly idealized assumptions.","The note clarifies that this is an estimate, not a forecast of realized storm speed; entrainment and water loading can reduce actual updrafts."]),
25:("A weather station uses rotating cups exposed to the wind; their rotation rate is converted to a wind-speed reading. Which instrument is being described?",[("Anemometer","The cup assembly responds to airflow; calibration relates its rotation to wind speed."),("Rain gauge","A rain gauge collects precipitation for a depth or amount reading, rather than sensing airflow."),("Barometer","A barometer measures atmospheric pressure, not cup rotation."),("Thermometer","A thermometer measures temperature; it has no wind-driven rotor." )],"An anemometer measures wind speed. In the common cup design, wind turns the cups and the instrument converts their rotation into a speed reading.",["The NWS glossary identifies an anemometer as an instrument for measuring wind speed.","NOAA's weather-station build guide describes a cup anemometer, supporting the rotating-cup detail in this scenario."],["The note adds the operational link between cup rotation and the wind-speed value, which is exactly what the station reads.","A cup rotor is characteristic of anemometry; the reading is speed rather than wind direction or accumulated precipitation."]),
26:("After a storm, an observer reads the graduated container used to collect precipitation. What quantity is this instrument designed to measure?",[("Precipitation amount","The collected water is read as an accumulated depth/amount over the observation interval."),("Wind speed","Wind speed is measured by an anemometer; collection in a graduated vessel is not a wind measurement."),("Air pressure","Pressure requires a barometer and is not inferred from the collected water volume."),("Air temperature","Temperature is read by a thermometer; the container records precipitation." )],"A rain gauge collects precipitation so its amount can be measured, commonly reported as a depth over a specified interval.",["The NWS glossary defines a rain gauge by its precipitation-measurement purpose.","NOAA's weather-station guide describes using a graduated collection vessel, matching the observation in the stem."],["The keyed quantity is rainfall/precipitation amount, not the vessel's capacity or the storm's intensity by itself.","A graduated collector allows accumulated precipitation to be read as depth, which is the conventional reportable quantity."]),
27:("A lightning mapping display shows a discharge path connecting regions inside one cloud, with no ground contact. Which lightning category best fits the mapped path?",[("Cloud-to-ground lightning","This category requires a channel between a cloud and the ground; the mapped path has no ground contact."),("In-cloud lightning","The channel connects regions within one cloud, which is the defining path described by the map."),("Heat lightning","This informal term describes distant storm flashes seen without audible thunder, not a discharge-path class."),("Staccato lightning","Staccato describes a brief, single-return-stroke cloud-to-ground flash, not an internal cloud channel." )],"Lightning is an electrical discharge. A channel that connects regions within a cloud is classified as in-cloud lightning; cloud-to-ground lightning instead has a channel reaching the surface.",["The NWS lightning glossary distinguishes in-cloud discharges from cloud-to-ground channels by their path endpoints.","The map gives path geometry rather than a viewing condition, allowing classification by where the channel connects."],["The selected category matches both endpoints shown inside the same cloud and the absence of any ground connection.","An in-cloud flash can illuminate a cloud without producing a cloud-to-ground strike; the label describes the electrical path."]),
28:("During a storm, a distant flash is followed by a low rolling acoustic wave. Which weather phenomenon is the sound itself?",[("Lightning","Lightning is the electrical discharge and visible flash; it produces the sound but is not the sound."),("Thunder","Thunder is the sound generated as lightning rapidly heats and expands the surrounding air."),("Rainfall","Rainfall can make noise, but the described delayed rolling wave follows a lightning flash."),("Wind gust","A gust is moving air; it does not name the acoustic result of a lightning channel." )],"Thunder is the acoustic effect of lightning: rapid heating makes the surrounding air expand suddenly, generating a pressure wave heard as a rumble or crack.",["The NWS thunder glossary links thunder to the sound produced by lightning's rapid heating of air.","The stem asks for the acoustic phenomenon and distinguishes it from the electrical event, precipitation, and wind."],["The note adds the physical mechanism—rapid heating and expansion—rather than restating that thunder is a sound.","Rolling or cracking describes how the pressure wave is heard; the source phenomenon remains thunder regardless of distance."]),
29:("In a ray diagram for a single faint bow outside the primary, light makes two internal reflections in each raindrop and its colour order is reversed. Which bow is shown?",[("Primary rainbow","The primary bow results from one internal reflection and has the opposite colour order to the described faint outer arc."),("Secondary rainbow","Two internal reflections produce the fainter outer bow and reverse its colour sequence relative to the primary."),("Supernumerary bow","Supernumerary bands are closely spaced interference fringes adjacent to a bow, not the outer two-reflection arc described here."),("Higher-order rainbow","Higher-order bows involve more than two internal reflections and occur at different viewing angles." )],"The secondary rainbow is produced by two internal reflections inside raindrops. It appears outside the primary, is fainter, and has reversed colour order; these observations identify that single outer bow.",["The NWS Flagstaff explanation connects two internal reflections with the secondary bow and its reversed colour sequence.","The stem specifies one outer arc and the ray path, separating it from paired-bow displays and higher-order or interference arcs."],["The two-reflection ray path is the defining optical distinction and explains why the colour order reverses.","The outer position and lower brightness provide independent observations consistent with a secondary bow, rather than merely naming a double-bow scene."])
}

def compact(x,sort=False): return json.dumps(x,ensure_ascii=False,separators=(',',':'),sort_keys=sort).encode()
def sha(x,sort=False): return hashlib.sha256(compact(x,sort)).hexdigest()
for i,(prompt,ans,expl,r1,r2) in D.items():
 c=cards[i]; x=c['proposedCard']; x['prompt']=prompt; x['answers']=[{'text':t,'note':n} for t,n in ans]; x['correctIndex']=c['frozenCorrectIndex']; x['explanation']=expl
 # preserve frozen correct slot: for 20-29, the content at frozen key must be the intended keyed answer
 x['source']['verifiedAt']='2026-10-14'
 key=x['correctIndex']; lit={'prompt':prompt,'orderedAnswerTexts':[a[0] for a in ans],'correctIndex':key,'correctAnswerText':ans[key][0]}
 c['literalGroupRecipes']['promptAnswersKey']['literal']=lit
 c['sixGroupSHA256']={'promptAnswersKey':sha(lit),'explanation':sha(expl)}
 for j,(_,note) in enumerate(ans): c['sixGroupSHA256'][f'note{j}']=sha(note)
 c['proposedCardCanonicalSHA256']=sha(x,True)
 c['classSHA256']=sha(c['frozenClass'])
 c['metadataSHA256']=sha(x['source'],True)
 c['ownSourceEditorialReasons']={'prompt+orderedAnswers+key':r1,'explanation':r2}
 for j,(_,note) in enumerate(ans): c['ownSourceEditorialReasons'][f'note{j}']=[r2[0],r1[1]]
 c['difficultyAndMetadataSourceEditorialReasons']={'class':[f"The frozen class for index {i} is {c['frozenClass']} and remains unchanged.",f"The multi-step reasoning demand in index {i} is consistent with its frozen {c['frozenClass']} classification."], 'source':[f"The display citation remains the captured primary source: {x['source']['title']} ({x['source']['url']}).", "Source-capture bindings and raw provenance remain attached unchanged; this authoring packet does not claim qualification or quality credit."]}
 c['currentCardCanonicalSHA256']=c['currentCardCanonicalSHA256']
# retain package-level immutable evidence; no mutation beyond authoring fields
open(P,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('written',len(D))
